-- Production-faithful STRUCTURE (no rows) of the tables the candidate touches, generated
-- 2026-11-06 from live catalog metadata of urwnbskrtoplgnkkxuvl (read-only). Includes the
-- existing bookings_alert trigger. uuid_generate_v4 defaults swapped to gen_random_uuid.
create role anon; create role authenticated; create role service_role;
create schema auth;
-- auth.uid() body copied from the live project (reads PostgREST's request.jwt.claims).
create function auth.uid() returns uuid language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''), (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub'))::uuid $$;
grant usage on schema auth to anon,authenticated;
grant execute on function auth.uid() to anon,authenticated;
create table public.people (id uuid default gen_random_uuid() not null, phone text not null, phone_verified boolean default false not null, auth_user_id uuid, display_name text, created_at timestamp with time zone default now() not null, sms_opt_in boolean default true not null, constraint people_phone_e164_chk CHECK ((phone ~ '^\+[1-9]\d{6,14}$'::text)), constraint people_pkey PRIMARY KEY (id), constraint people_phone_key UNIQUE (phone), constraint people_auth_user_id_key UNIQUE (auth_user_id));
create table public.business_workspaces (id uuid default gen_random_uuid() not null, slug text not null, name text not null, workspace_type text default 'business_client'::text not null, parent_workspace_id uuid, industry_pack text, status text default 'active'::text not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, constraint business_workspaces_workspace_type_check CHECK ((workspace_type = ANY (ARRAY['platform'::text, 'holding'::text, 'sports_org'::text, 'home_services'::text, 'media_brand'::text, 'review_platform'::text, 'education'::text, 'business_client'::text]))), constraint business_workspaces_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text, 'archived'::text]))), constraint business_workspaces_pkey PRIMARY KEY (id), constraint business_workspaces_slug_key UNIQUE (slug), constraint business_workspaces_parent_workspace_id_fkey FOREIGN KEY (parent_workspace_id) REFERENCES business_workspaces(id) ON DELETE RESTRICT);
create table public.workspace_members (id uuid default gen_random_uuid() not null, workspace_id uuid not null, person_id uuid not null, status text default 'active'::text not null, created_at timestamp with time zone default now() not null, constraint workspace_members_status_check CHECK ((status = ANY (ARRAY['active'::text, 'pending'::text, 'revoked'::text]))), constraint workspace_members_pkey PRIMARY KEY (id), constraint workspace_members_workspace_id_person_id_key UNIQUE (workspace_id, person_id), constraint workspace_members_workspace_id_fkey FOREIGN KEY (workspace_id) REFERENCES business_workspaces(id) ON DELETE CASCADE, constraint workspace_members_person_id_fkey FOREIGN KEY (person_id) REFERENCES people(id) ON DELETE CASCADE);
create table public.workspace_roles (id uuid default gen_random_uuid() not null, workspace_id uuid not null, person_id uuid not null, role text not null, created_at timestamp with time zone default now() not null, constraint workspace_roles_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'admin'::text, 'staff'::text, 'coach'::text, 'customer'::text, 'viewer'::text]))), constraint workspace_roles_pkey PRIMARY KEY (id), constraint workspace_roles_workspace_id_person_id_role_key UNIQUE (workspace_id, person_id, role), constraint workspace_roles_workspace_id_fkey FOREIGN KEY (workspace_id) REFERENCES business_workspaces(id) ON DELETE CASCADE, constraint workspace_roles_person_id_fkey FOREIGN KEY (person_id) REFERENCES people(id) ON DELETE CASCADE);
create table public.organizations (id uuid default gen_random_uuid() not null, created_at timestamp with time zone default now() not null, name text not null, sport text, org_type text, published boolean default false, updated_at timestamp with time zone default now(), constraint organizations_org_type_check CHECK ((org_type = ANY (ARRAY['travel'::text, 'school'::text, 'league'::text, 'club'::text, 'recreation'::text, 'other'::text]))), constraint organizations_pkey PRIMARY KEY (id));
create table public.teams (id uuid default gen_random_uuid() not null, organization_id uuid, name text not null, age_group text, level text, season text, sport text, external_ref text, is_active boolean default true not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, constraint teams_level_check CHECK (((level IS NULL) OR (level = ANY (ARRAY['house'::text, 'travel'::text, 'elite'::text, 'other'::text])))), constraint teams_pkey PRIMARY KEY (id), constraint teams_organization_id_fkey FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE SET NULL);
create table public.facilities (id uuid default gen_random_uuid() not null, name text not null, slug text, facility_type text, address text, city text, state text, contact_email text, contact_phone text, access_code text not null, logo_url text, description text, is_active boolean default true, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), constraint facilities_pkey PRIMARY KEY (id), constraint facilities_slug_key UNIQUE (slug));
create table public.facility_areas (id uuid default gen_random_uuid() not null, facility_id uuid not null, name text not null, area_type text default 'other'::text, color text default '#5B6B82'::text, display_order integer default 0, is_active boolean default true, created_at timestamp with time zone default now(), constraint facility_areas_area_type_check CHECK ((area_type = ANY (ARRAY['ice'::text, 'field'::text, 'court'::text, 'room'::text, 'training'::text, 'other'::text]))), constraint facility_areas_pkey PRIMARY KEY (id), constraint facility_areas_facility_id_fkey FOREIGN KEY (facility_id) REFERENCES facilities(id) ON DELETE CASCADE);
create table public.coaches (id uuid default gen_random_uuid() not null, coach_name text, organization_id uuid, constraint coaches_pkey PRIMARY KEY (id));
create table public.families (id uuid default gen_random_uuid() not null, family_name text not null, email text not null, phone text not null, pin text not null, constraint families_pkey PRIMARY KEY (id));
create table public.athletes (id uuid default gen_random_uuid() not null, family_id uuid not null, first_name text not null, last_name text not null, constraint athletes_pkey PRIMARY KEY (id), constraint athletes_family_id_fkey FOREIGN KEY (family_id) REFERENCES families(id) ON DELETE CASCADE);
create table public.bookings (id uuid default gen_random_uuid() not null, facility_id uuid not null, area_id uuid not null, booking_type text not null, title text, customer_name text, contact_email text, contact_phone text, organization_id uuid, coach_id uuid, start_time timestamp with time zone not null, end_time timestamp with time zone not null, amount numeric default 0, status text default 'confirmed'::text, is_recurring boolean default false, recurrence_rule text, notes text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), athlete_id uuid, family_id uuid, constraint bookings_booking_type_check CHECK ((booking_type = ANY (ARRAY['organization_rental'::text, 'team_rental'::text, 'coach_rental'::text, 'private_rental'::text, 'birthday_party'::text, 'tournament'::text, 'camp'::text, 'clinic'::text, 'maintenance'::text, 'open_skate'::text]))), constraint bookings_status_check CHECK ((status = ANY (ARRAY['confirmed'::text, 'cancelled'::text, 'maintenance'::text]))), constraint bookings_pkey PRIMARY KEY (id), constraint bookings_facility_id_fkey FOREIGN KEY (facility_id) REFERENCES facilities(id) ON DELETE CASCADE, constraint bookings_area_id_fkey FOREIGN KEY (area_id) REFERENCES facility_areas(id) ON DELETE CASCADE, constraint bookings_organization_id_fkey FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE SET NULL, constraint bookings_coach_id_fkey FOREIGN KEY (coach_id) REFERENCES coaches(id) ON DELETE SET NULL, constraint bookings_athlete_id_fkey FOREIGN KEY (athlete_id) REFERENCES athletes(id) ON DELETE SET NULL, constraint bookings_family_id_fkey FOREIGN KEY (family_id) REFERENCES families(id) ON DELETE SET NULL);
create table public.open_slots (id uuid default gen_random_uuid() not null, facility_id uuid not null, area_id uuid not null, source_booking_id uuid, source text not null, start_time timestamp with time zone not null, end_time timestamp with time zone not null, price numeric default 0, reason text, status text default 'open'::text, claimed_by_name text, claimed_by_email text, claimed_by_phone text, views integer default 0, created_at timestamp with time zone default now(), claimed_at timestamp with time zone, claimed_by_athlete_id uuid, claimed_by_family_id uuid, constraint open_slots_source_check CHECK ((source = ANY (ARRAY['cancellation'::text, 'unbooked'::text]))), constraint open_slots_status_check CHECK ((status = ANY (ARRAY['open'::text, 'claimed'::text, 'expired'::text]))), constraint open_slots_pkey PRIMARY KEY (id), constraint open_slots_facility_id_fkey FOREIGN KEY (facility_id) REFERENCES facilities(id) ON DELETE CASCADE, constraint open_slots_area_id_fkey FOREIGN KEY (area_id) REFERENCES facility_areas(id) ON DELETE CASCADE, constraint open_slots_source_booking_id_fkey FOREIGN KEY (source_booking_id) REFERENCES bookings(id) ON DELETE SET NULL);
create table public.calendar_events (id uuid default gen_random_uuid() not null, source_module text not null, source_table text not null, source_id text not null, title text not null, description text, event_type text, start_time timestamp with time zone not null, end_time timestamp with time zone, location_name text, location_address text, organization_id uuid, coach_id uuid, facility_id uuid, is_public boolean default false, status text default 'active'::text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), is_conflict boolean default false not null, is_duplicate boolean default false not null, workspace_id uuid, constraint calendar_events_status_check CHECK ((status = ANY (ARRAY['active'::text, 'cancelled'::text, 'completed'::text]))), constraint calendar_events_pkey PRIMARY KEY (id), constraint calendar_events_source_module_source_table_source_id_key UNIQUE (source_module, source_table, source_id), constraint calendar_events_source_module_check CHECK ((source_module = ANY (ARRAY['homehuddle'::text, 'athletehuddle'::text, 'coacheshuddle'::text, 'organizationhuddle'::text, 'facilityhuddle'::text, 'tournamenthuddle'::text, 'workflow'::text]))));
create table public.alert_recipients (id uuid default gen_random_uuid() not null, label text not null, phone text not null, active boolean default true not null, alert_leads boolean default true not null, alert_bookings boolean default true not null, alert_submissions boolean default true not null, created_at timestamp with time zone default now() not null, constraint alert_recipients_pkey PRIMARY KEY (id));
create table public.sms_outbox (id uuid default gen_random_uuid() not null, person_id uuid, phone text not null, family_id uuid, event_ref text not null, change_hash text not null, message text not null, status text default 'pending'::text not null, attempts integer default 0 not null, error text, created_at timestamp with time zone default now() not null, sent_at timestamp with time zone, constraint sms_outbox_pkey PRIMARY KEY (id), constraint sms_outbox_dedup UNIQUE (person_id, event_ref, change_hash));
CREATE UNIQUE INDEX alert_recipients_phone_uniq ON public.alert_recipients USING btree (phone);
-- Production RLS posture: RLS on, no policies, no client grants on facility tables.
do $$declare t text; begin foreach t in array array['people','business_workspaces','workspace_members','workspace_roles','organizations','teams','facilities','facility_areas','coaches','families','athletes','bookings','open_slots','calendar_events','alert_recipients','sms_outbox'] loop execute format('alter table public.%I enable row level security',t); end loop; end$$;
CREATE OR REPLACE FUNCTION public.current_person_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ select id from public.people where auth_user_id = auth.uid() limit 1; $function$;
CREATE OR REPLACE FUNCTION public.enqueue_internal_alert(p_kind text, p_event_ref text, p_message text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
declare v_count integer := 0;
begin
  insert into public.sms_outbox (person_id, phone, event_ref, change_hash, message, status)
  select null, r.phone, p_event_ref, md5(p_message || r.phone), left(p_message, 480), 'pending'
  from public.alert_recipients r
  where r.active and case p_kind when 'lead' then r.alert_leads when 'booking' then r.alert_bookings when 'submission' then r.alert_submissions else true end
  on conflict do nothing;
  get diagnostics v_count = row_count;
  return v_count;
end; $function$;
CREATE OR REPLACE FUNCTION public.trg_bookings_alert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
begin
  begin
    perform public.enqueue_internal_alert('booking','booking:' || new.id::text,
      'NEW BOOKING - $' || coalesce(new.amount, 0)::text || E'\n' || coalesce(new.customer_name, 'Unknown')
        || E'\n' || coalesce(new.booking_type, 'rental') || E'\n' || to_char(new.start_time, 'Mon DD HH12:MI AM')
        || E'\nCall: ' || coalesce(new.contact_phone, 'no phone'));
  exception when others then null;
  end;
  return new;
end; $function$;
create trigger bookings_alert after insert on public.bookings for each row execute function public.trg_bookings_alert();
